package app.quietkey;
import org.junit.Test;
import static org.junit.Assert.*;
public final class PasswordCipherTest {
    @Test public void argon2idRfc9106KnownAnswer(){byte[] password=new byte[32],salt=new byte[16],secret=new byte[8],ad=new byte[12];java.util.Arrays.fill(password,(byte)1);java.util.Arrays.fill(salt,(byte)2);java.util.Arrays.fill(secret,(byte)3);java.util.Arrays.fill(ad,(byte)4);org.bouncycastle.crypto.generators.Argon2BytesGenerator generator=new org.bouncycastle.crypto.generators.Argon2BytesGenerator();generator.init(new org.bouncycastle.crypto.params.Argon2Parameters.Builder(org.bouncycastle.crypto.params.Argon2Parameters.ARGON2_id).withVersion(19).withIterations(3).withMemoryAsKB(32).withParallelism(4).withSalt(salt).withSecret(secret).withAdditional(ad).build());byte[] out=new byte[32];generator.generateBytes(password,out);StringBuilder hex=new StringBuilder();for(byte b:out)hex.append(String.format("%02x",b&255));assertEquals("0d640df58d78766c08c037a34a8b53c9d01ef0452d75b65eb52520e96b01e659",hex.toString());}
    @Test public void passwordUnlockAndWrongPasswordAndTampering()throws Exception{char[] pass="four random words and more".toCharArray();byte[] master=Protocol.random(32),box=PasswordCipher.seal(pass,master);assertArrayEquals(master,PasswordCipher.open(pass,box));assertThrows(javax.crypto.AEADBadTagException.class,()->PasswordCipher.open("wrong password".toCharArray(),box));box[box.length-1]^=1;assertThrows(javax.crypto.AEADBadTagException.class,()->PasswordCipher.open(pass,box));}
    @Test public void parametersAndLengthsAreBounded()throws Exception{assertThrows(IllegalArgumentException.class,()->PasswordCipher.seal("short".toCharArray(),new byte[32]));assertThrows(Exception.class,()->PasswordCipher.open(new char[129],new byte[0]));assertThrows(Exception.class,()->PasswordCipher.open("correct password".toCharArray(),new byte[1000]));}
    @Test public void passwordChangeCanRewrapTheSameVaultKey()throws Exception{byte[] master=Protocol.random(32),box=PasswordCipher.seal("old strong password".toCharArray(),master),key=PasswordCipher.open("old strong password".toCharArray(),box),next=PasswordCipher.seal("new strong password".toCharArray(),key);assertArrayEquals(master,PasswordCipher.open("new strong password".toCharArray(),next));assertThrows(javax.crypto.AEADBadTagException.class,()->PasswordCipher.open("old strong password".toCharArray(),next));}
}
